package java.util.concurrent.locks;
import java.util.concurrent.TimeUnit;
public class ReentrantReadWriteLock implements ReadWriteLock,java.io.Serializable {
 private final ReentrantLock lock;private final ReadLock read;private final WriteLock write;private int reads;public ReentrantReadWriteLock(){this(false);}public ReentrantReadWriteLock(boolean fair){lock=new ReentrantLock(fair);read=new ReadLock(this);write=new WriteLock(this);}public ReadLock readLock(){return read;}public WriteLock writeLock(){return write;}public boolean isFair(){return lock.isFair();}public int getReadLockCount(){return reads;}public int getWriteHoldCount(){return lock.getHoldCount();}public boolean isWriteLocked(){return lock.isLocked();}public boolean isWriteLockedByCurrentThread(){return lock.isHeldByCurrentThread();}
 public static class ReadLock implements Lock,java.io.Serializable {final ReentrantReadWriteLock p;protected ReadLock(ReentrantReadWriteLock p){this.p=p;}public void lock(){p.reads++;}public void lockInterruptibly()throws InterruptedException{if(Thread.interrupted())throw new InterruptedException();lock();}public boolean tryLock(){lock();return true;}public boolean tryLock(long n,TimeUnit u)throws InterruptedException{if(u==null)throw new NullPointerException();return tryLock();}public void unlock(){if(p.reads==0)throw new IllegalMonitorStateException();p.reads--;}public Condition newCondition(){throw new UnsupportedOperationException();}}
 public static class WriteLock implements Lock,java.io.Serializable {final ReentrantReadWriteLock p;protected WriteLock(ReentrantReadWriteLock p){this.p=p;}public void lock(){p.lock.lock();}public void lockInterruptibly()throws InterruptedException{p.lock.lockInterruptibly();}public boolean tryLock(){return p.reads==0&&p.lock.tryLock();}public boolean tryLock(long n,TimeUnit u)throws InterruptedException{if(u==null)throw new NullPointerException();return tryLock();}public void unlock(){p.lock.unlock();}public Condition newCondition(){return p.lock.newCondition();}public boolean isHeldByCurrentThread(){return p.lock.isHeldByCurrentThread();}public int getHoldCount(){return p.lock.getHoldCount();}}
}
